import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/bgLMI2u.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/availability-vs-consistency.md","filePath":"core-concepts/availability-vs-consistency.md"}'),n={name:"core-concepts/availability-vs-consistency.md"};function s(l,e,c,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="availability-vs-consistency" tabindex="-1">Availability vs consistency <a class="header-anchor" href="#availability-vs-consistency" aria-label="Permalink to &quot;Availability vs consistency&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Availability vs consistency.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><h3 id="cap-theorem" tabindex="-1">CAP theorem <a class="header-anchor" href="#cap-theorem" aria-label="Permalink to &quot;CAP theorem&quot;">​</a></h3><p align="center"><img src="'+o+'"><br><i><a href="https://robertgreiner.com/cap-theorem-revisited">Source: CAP theorem revisited</a></i></p><p>In a distributed computer system, you can only support two of the following guarantees:</p><ul><li><strong>Consistency</strong> - Every read receives the most recent write or an error</li><li><strong>Availability</strong> - Every request receives a response, without guarantee that it contains the most recent version of the information</li><li><strong>Partition Tolerance</strong> - The system continues to operate despite arbitrary partitioning due to network failures</li></ul><p><em>Networks aren&#39;t reliable, so you&#39;ll need to support partition tolerance. You&#39;ll need to make a software tradeoff between consistency and availability.</em></p><h4 id="cp-consistency-and-partition-tolerance" tabindex="-1">CP - consistency and partition tolerance <a class="header-anchor" href="#cp-consistency-and-partition-tolerance" aria-label="Permalink to &quot;CP - consistency and partition tolerance&quot;">​</a></h4><p>Waiting for a response from the partitioned node might result in a timeout error. CP is a good choice if your business needs require atomic reads and writes.</p><h4 id="ap-availability-and-partition-tolerance" tabindex="-1">AP - availability and partition tolerance <a class="header-anchor" href="#ap-availability-and-partition-tolerance" aria-label="Permalink to &quot;AP - availability and partition tolerance&quot;">​</a></h4><p>Responses return the most readily available version of the data available on any node, which might not be the latest. Writes might take some time to propagate when the partition is resolved.</p><p>AP is a good choice if the business needs to allow for <a href="#eventual-consistency">eventual consistency</a> or when the system needs to continue working despite external errors.</p><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="https://robertgreiner.com/cap-theorem-revisited/" target="_blank" rel="noreferrer">CAP theorem revisited</a></li><li><a href="http://ksat.me/a-plain-english-introduction-to-cap-theorem" target="_blank" rel="noreferrer">A plain english introduction to CAP theorem</a></li><li><a href="https://github.com/henryr/cap-faq" target="_blank" rel="noreferrer">CAP FAQ</a></li><li><a href="https://www.youtube.com/watch?v=k-Yaq8AHlFA" target="_blank" rel="noreferrer">The CAP theorem</a></li></ul>',14)])])}const y=t(n,[["render",s]]);export{m as __pageData,y as default};
